for t in range(0,96,4):
 m=d[t]>15
 ys,xs=np.where(m)
 print(f'{t:2d}: bbox {xs.min():3d},{ys.min():3d}-{xs.max():3d},{ys.max():3d} n={len(xs):4d} centroid={xs.mean():.1f},{ys.mean():.1f}')
