import numpy as np
z=np.load('source_pixels.npz')['rgb'].astype(int)
# foreground mask relative to final background at t=0. print RGB and mask around center
bg=z[95]; a=z[0]
for y in range(62,88):
 vals=[]
 for x in range(226,252):
  p=a[y,x]; d=np.max(np.abs(p-bg[y,x]));
  if d>10: vals.append(f'{p[0]:3d},{p[1]:3d},{p[2]:3d}')
  else: vals.append('    .    ')
 print(y,' | '.join(vals[:12]))
